"""Publish actual saved r10 changes, matched r9 comparison and honest work outlook."""
from pathlib import Path
import json,hashlib,shutil,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-layered-r10'
OLD=OUT.parent/'rift-titan-crystal-limbs-r9'
row=json.loads((OUT/'refinement-metrics.json').read_text());ID=row['id'];previous='underworld-boss-rift-titan-crystal-limbs-r9'
checks={n:json.loads((OUT/(n+'.json')).read_text()) for n in ('verification','attachment-verification','closing-face-verification','crystal-face-verification','thorax-face-verification','side-orientation')}
assert row['triangles']==checks['verification']['triangles']==1800
assert checks['attachment-verification']['result']=='PASS' and checks['attachment-verification']['endpoints']==76
for n,total in [('closing-face-verification',8064),('crystal-face-verification',14112),('thorax-face-verification',2016)]:assert checks[n]['result']=='PASS' and checks[n]['sampled_points']==total and checks[n]['poses']==36 and checks[n]['max_outside_distance_metres']==0
sha=hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest();assert checks['verification']['source_sha256']==checks['side-orientation']['source_sha256']==sha and checks['side-orientation']['camera_direction'][0]<0
(OUT/'before').mkdir(exist_ok=True)
views=('three-quarter','front','side','front-clay','side-clay','side-reference')
for view in views:shutil.copy2(OLD/(previous+'--'+view+'.png'),OUT/'before'/(previous+'--'+view+'.png'))
for p in ('concept-front.png','concept-side.png'):shutil.copy2(OLD/p,OUT/p)
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — layered stone and weathering r10</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.reference img{{height:650px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}table{{border-collapse:collapse;width:100%;max-width:1150px}}td,th{{border:1px solid #526067;padding:12px;text-align:left}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}.reference img{{height:500px}}}}</style>
<h1>Rift Titan — layered stone and weathering r10</h1>
<p>The crest now rakes forward in profile, using the preserved online crown authoring. The paired upper-thorax stones are broader and seated into their shoulder masses. Sixteen limb plates are longer, oblique and staggered in depth, so they overlap rather than forming short repeated chunks; their attached crystals follow those changes. The retained core crystals form a more irregular cluster. The lower head, original arm-root blends and both torso rings remain.</p>
<p>The owned surface atlas introduces blue-gray/ochre stone patches, shallow fracture normals, olive lichen, dark corroded ribs and varied violet crystals. The first stone render was too pale and softly mottled, prompting a darker palette and sharper patch contrast. Surface placement and fine rock fragmentation are still unfinished.</p>
<p><strong>1,800 triangles · native Stone Golem 1,200 · 1.500× · cap 1,800.</strong> One mesh/material, four packed 512px maps, eight original bone identities and seven actions. No runtime promotion.</p>
<h2>Previous and current — matched cameras</h2><div><button data-view="three-quarter">Surface</button><button data-view="front">Front surface</button><button data-view="side">True side surface</button><button data-view="front-clay">Front clay</button><button data-view="side-clay">True side clay</button><button data-view="side-reference">Angled side</button></div><div class="pair"><figure><img id="before" src="before/{previous}--three-quarter.png" alt="Preserved r9"><figcaption>Previous r9</figcaption></figure><figure><img id="after" src="{ID}--three-quarter.png" alt="Current r10"><figcaption>Current r10 — forward crest, overlapping strata and initial weathered atlas</figcaption></figure></div>
<h2>Front shape reference</h2><div class="pair reference"><figure><img src="concept-front.png" alt="Concept front"><figcaption>Adopted front concept</figcaption></figure><figure><img src="{ID}--front-reference.png" alt="Current front clay"><figcaption>Current front clay — coarse stone contours still require individual remodeling</figcaption></figure></div>
<h2>Left-facing shape reference</h2><div class="pair reference"><figure><img src="concept-side.png" alt="Concept side"><figcaption>Concept — front/head left, back right</figcaption></figure><figure><img src="{ID}--side-reference-clay.png" alt="Current left-facing clay"><figcaption>Current angled side — forward-raking crest; true profile available above</figcaption></figure></div>
<h2>Adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Full source concept sheet">
<h2>Remaining work toward an 85% visual match</h2><p><strong>Planning estimate: 8–12 more substantial passes after r10.</strong> Current rating remains “not great”; this study is not claimed to be at 85%. No automated similarity score exists. This range assumes meaningful individual remodeling each pass and retains the 1,800-triangle/four-512px-map envelope. Regressions or animation problems can extend it.</p>
<table><tr><th>Work remaining</th><th>Estimated passes</th></tr><tr><td>Head, mantle and limb contour remodeling; chipped strata and topology redistribution</td><td>3–4</td></tr><tr><td>Crystal core, head cleft and broken floating crest arrangement</td><td>2–3</td></tr><tr><td>Directional stone fractures, purposeful weathering, corrosion and crystal emission</td><td>2–3</td></tr><tr><td>Coordinated corrections, trimming and deformation/runtime review</td><td>1–2</td></tr></table>
<p>Target: dominant silhouettes and anatomy agree in front and left-facing side; important stone/metal/crystal features read correctly; remaining differences are mainly secondary chips and texture nuances. The user's visual judgment remains the acceptance authority. Revisit this estimate after two more passes. <a href="../../RIFT-TITAN-REFINEMENT-OUTLOOK.md">Detailed outlook</a>.</p>
<p>All 76 support groups pass rest and 35 sampled action poses. Arm/digit basal faces pass 8,064 interior/edge samples; crystal bases pass 14,112; two new upper-thorax sections pass 2,016. These checks use the saved evaluated mesh across 36 poses, with zero measured outside distance. Native every-frame deformation and live performance remain pending. Adequately reworked boss tally remains 1/6.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--detail.png">Torso close-up</a> · <a href="{ID}--attack.png">Attack pose</a> · <a href="layer-authoring.json">Current changes</a> · <a href="verification.json">Mesh/export checks</a> · <a href="attachment-verification.json">Support checks</a> · <a href="closing-face-verification.json">Arm/digit basal faces</a> · <a href="crystal-face-verification.json">Crystal basal faces</a> · <a href="thorax-face-verification.json">Upper-thorax basal faces</a> · <a href="side-orientation.json">Camera direction</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='before/{previous}--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_wrapped_torso.py','tools/rift_titan_silhouette_fit.py','tools/rift_titan_joint_silhouette.py','tools/rift_titan_crystal_limbs.py','tools/rift_titan_crown_profile.py','tools/rift_titan_layered_weathering.py','tools/refine-rift-titan-layered-r10.py','tools/review-rift-titan-layered-r10.py','tools/review-rift-titan-silhouette-r7.py','tools/verify-rift-titan-layered-r10.py','tools/verify-rift-titan-crystal-limbs-r9.py','tools/publish-rift-titan-layered-r10.py',row['source'],'assets/models/studies/'+previous+'.blend','docs/art/creature-concepts/2026-10-03/the-rift-titan.png','docs/art/creature-models/RIFT-TITAN-REFINEMENT-OUTLOOK.md']
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},scope='r9 limbs plus preserved online crest and mantle specifications; owned surface shaders',acceptance='unaccepted; no 85% match claim; tally 1/6',estimated_remaining_substantial_passes=[8,12]),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
for view in views:assert (OUT/(ID+'--'+view+'.png')).is_file()
print('VERIFIED r10 gallery, saved source hashes, left-facing comparisons, 76 supports, budget and remaining-work outlook')
